function buildAiPromptWithStyles(basePrompt, componentNames) {
  const names = (Array.isArray(componentNames) ? componentNames : [componentNames])
    .filter(Boolean)
    .filter((name, index, arr) => arr.indexOf(name) === index);
  const parts = [String(basePrompt || '').trim()];

  parts.push('');
  parts.push('Дизайн-токены SB (обязательно: цвета, тени, радиусы, толщина границ, отступы, focus-ring):');
  parts.push('\`\`\`css');
  parts.push(designSystemTokens.trim());
  parts.push('\`\`\`');

  const cssBlocks = names
    .map((name) => {
      const css = componentCssSnippets[name];
      if (!css) return '';
      return '### ' + name + '\n\`\`\`css\n' + css.trim() + '\n\`\`\`';
    })
    .filter(Boolean);

  if (cssBlocks.length) {
    parts.push('');
    parts.push('CSS компонентов (воспроизведи визуал один в один — box-shadow, border-radius, border-width, цвета):');
    parts.push(cssBlocks.join('\n\n'));
  }

  return parts.join('\n');
}
